inline void run_conv_layer(
    const std::vector<Vec4>& src, int w, int h,
    const Layer& layer, bool crelu_input,
    std::vector<Vec4>& dst
) {
    dst.resize(size_t(w) * size_t(h));
    auto sample = [&](int x, int y) -> const Vec4& {
        x = std::clamp(x, 0, w - 1);
        y = std::clamp(y, 0, h - 1);
        return src[size_t(y * w + x)];
    };
    for (int y = 0; y < h; ++y) {
        for (int x = 0; x < w; ++x) {
            float rx = layer.bias[0], ry = layer.bias[1], rz = layer.bias[2], rw = layer.bias[3];
            for (int ti = 0; ti < layer.num_taps; ++ti) {
                const Tap& t = layer.taps[ti];
                const Vec4& s = sample(x + t.dx, y + t.dy);
                float vx, vy, vz, vw;
                if (!crelu_input) {
                    vx = s.x; vy = s.y; vz = s.z; vw = s.w;
                } else if (t.branch == 0) {
                    vx = std::max(s.x, 0.0f); vy = std::max(s.y, 0.0f);
                    vz = std::max(s.z, 0.0f); vw = std::max(s.w, 0.0f);
                } else {
                    vx = std::max(-s.x, 0.0f); vy = std::max(-s.y, 0.0f);
                    vz = std::max(-s.z, 0.0f); vw = std::max(-s.w, 0.0f);
                }
                // GLSL column-major mat4 * vec4: col0*vx + col1*vy + col2*vz + col3*vw
                rx += t.m[0] * vx + t.m[4] * vy + t.m[8]  * vz + t.m[12] * vw;
                ry += t.m[1] * vx + t.m[5] * vy + t.m[9]  * vz + t.m[13] * vw;
                rz += t.m[2] * vx + t.m[6] * vy + t.m[10] * vz + t.m[14] * vw;
                rw += t.m[3] * vx + t.m[7] * vy + t.m[11] * vz + t.m[15] * vw;
            }
            dst[size_t(y * w + x)] = {rx, ry, rz, rw};
        }
    }
}

// Run 4-layer Anime4K Restore_CNN_Soft_S in-place on [0..1] RGB image (de-blocks & restores edges!)
inline void apply_restore_cnn(std::vector<Vec4>& img, int w, int h,
                              std::vector<Vec4>& b0, std::vector<Vec4>& b1) {
    run_conv_layer(img, w, h, kRestoreSoftS[0], false, b0);
    run_conv_layer(b0,  w, h, kRestoreSoftS[1], true,  b1);
    run_conv_layer(b1,  w, h, kRestoreSoftS[2], true,  b0);
    run_conv_layer(b0,  w, h, kRestoreSoftS[3], true,  b1);
    for (size_t i = 0; i < img.size(); ++i) {
        img[i].x = std::clamp(img[i].x + b1[i].x, 0.0f, 1.0f);
        img[i].y = std::clamp(img[i].y + b1[i].y, 0.0f, 1.0f);
        img[i].z = std::clamp(img[i].z + b1[i].z, 0.0f, 1.0f);
    }
}

// Run 5-pass Anime4K Upscale_CNN_x2 (or Upscale_Denoise_CNN_x2): 2x bilinear RGB + 2x2 sub-pixel CNN residual!
inline void apply_upscale_cnn_x2(
    const std::vector<Vec4>& src, int w, int h,
    const Layer model[4],
    std::vector<Vec4>& b0, std::vector<Vec4>& b1,
    std::vector<Vec4>& dst_2x
) {
    run_conv_layer(src, w, h, model[0], false, b0);
    run_conv_layer(b0,  w, h, model[1], true,  b1);
    run_conv_layer(b1,  w, h, model[2], true,  b0);
    run_conv_layer(b0,  w, h, model[3], true,  b1); // b1 = conv2d_last_tf (2x2 luminance sub-pixel residuals)

    const int w2 = w * 2;
    const int h2 = h * 2;
    dst_2x.resize(size_t(w2) * size_t(h2));

    auto sample_edi_bilinear = [&](float fx, float fy) -> Vec4 {
        int x0 = int(std::floor(fx));
        int y0 = int(std::floor(fy));
        float tx = fx - float(x0);
        float ty = fy - float(y0);
        int x0c = std::clamp(x0,     0, w - 1);
        int x1c = std::clamp(x0 + 1, 0, w - 1);
        int y0c = std::clamp(y0,     0, h - 1);
        int y1c = std::clamp(y0 + 1, 0, h - 1);
        const Vec4& c00 = src[size_t(y0c * w + x0c)];
        const Vec4& c10 = src[size_t(y0c * w + x1c)];
        const Vec4& c01 = src[size_t(y1c * w + x0c)];
        const Vec4& c11 = src[size_t(y1c * w + x1c)];

        // Edge-Directed Diagonal Interpolation (NEDI / xBR-style):
        // Compare NW-SE diagonal coherence vs NE-SW anti-diagonal coherence so 45-degree lines never stair-step!
        auto luma = [](const Vec4& c) -> float { return c.x * 0.299f + c.y * 0.587f + c.z * 0.114f; };
        float d_main = std::abs(luma(c00) - luma(c11));
        float d_anti = std::abs(luma(c10) - luma(c01));

        float w00 = (1.0f - tx) * (1.0f - ty);
        float w10 = tx * (1.0f - ty);
        float w01 = (1.0f - tx) * ty;
        float w11 = tx * ty;

        if (d_main + 0.03f < d_anti) {
            // Strong NW-SE edge: boost diagonal pair (c00, c11) at center
            float boost = 0.45f * std::min(w10, w01);
            w00 += boost; w11 += boost;
            w10 -= boost; w01 -= boost;
        } else if (d_anti + 0.03f < d_main) {
            // Strong NE-SW edge: boost anti-diagonal pair (c10, c01) at center
            float boost = 0.45f * std::min(w00, w11);
            w10 += boost; w01 += boost;
            w00 -= boost; w11 -= boost;
        }
        return {
            c00.x * w00 + c10.x * w10 + c01.x * w01 + c11.x * w11,
            c00.y * w00 + c10.y * w10 + c01.y * w01 + c11.y * w11,
            c00.z * w00 + c10.z * w10 + c01.z * w01 + c11.z * w11,
            1.0f
        };
    };

    for (int y2 = 0; y2 < h2; ++y2) {
        int sy = y2 >> 1;
        int iy = y2 & 1;
        float fy = (float(y2) + 0.5f) * 0.5f - 0.5f;
        for (int x2 = 0; x2 < w2; ++x2) {
            int sx = x2 >> 1;
            int ix = x2 & 1;
            float fx = (float(x2) + 0.5f) * 0.5f - 0.5f;
            Vec4 base = sample_edi_bilinear(fx, fy);
            const Vec4& res4 = b1[size_t(sy * w + sx)];
            int sub_idx = iy * 2 + ix;
            float delta = (sub_idx == 0) ? res4.x : ((sub_idx == 1) ? res4.y : ((sub_idx == 2) ? res4.z : res4.w));
            dst_2x[size_t(y2 * w2 + x2)] = {
                std::clamp(base.x + delta, 0.0f, 1.0f),
                std::clamp(base.y + delta, 0.0f, 1.0f),
                std::clamp(base.z + delta, 0.0f, 1.0f),
                1.0f
            };
        }
    }
}

